import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const p=JSON.parse('{"title":"1964年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1964年/核心总结.md","filePath":"01_letters/1964年/核心总结.md"}'),l={name:"01_letters/1964年/核心总结.md"};function n(s,a,i,_,d,h){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1964年-核心总结" tabindex="-1">1964年 核心总结 <a class="header-anchor" href="#_1964年-核心总结" aria-label="Permalink to &quot;1964年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1964年，道琼斯指数上涨18.7%，而巴菲特合伙企业的收益率达到27.8%，再度跑赢指数约9个百分点。当年合伙企业净资产从年初约1360万美元增长至1740万美元。巴菲特在信中指出，虽然市场整体表现强劲，但合伙企业超额收益的来源并非市场热点板块，而是来自低估类股票的均值回归以及部分套利操作的贡献。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>巴菲特在年度信中系统阐述了他对投资业务的分类框架，将合伙企业的投资策略明确划分为三大类：低估类（Generals）、套利类（Workouts）与控制类（Controls），并强调&quot;买入占业务90%&quot;这一核心原则，即至少有90%的仓位应配置于低估类投资。他特别指出，控制类投资虽然潜在回报高，但需要耐心等待合适的介入时机，不宜急于求成。</p><p>同年，巴菲特还深入分析了当时投资公司（封闭式基金与开放式基金）面临的结构性困境：管理层往往在牛市中积极扩张、在熊市中被动防守，违背了低买高卖的朴素原则，导致长期投资者受损。他以此为反面教材，进一步重申了独立判断、逆向思维的重要性。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特强调，投资成功的关键在于对企业内在价值的判断能力，而非对短期股价波动的预测。他坚持&quot;买入占业务90%&quot;的仓位原则——即当认定某标的价值被严重低估时，应敢于重仓持有，而非分散配置。这一理念为他后续集中持股的投资风格奠定了基础，也成为区分他与同期华尔街主流做法的重要标志。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>这一时期，本杰明·格雷厄姆的影响仍然贯穿巴菲特的投资方法论。尽管格雷厄姆本人已于1956年退休，但他的价值投资哲学——以低于清算价值或内在价值的价格买入证券——始终是巴菲特的底层逻辑。此外，盖洛德·斯特弗斯（Gaylord Stevens）等早期合伙人也持续参与其中，共同见证了合伙企业从创立走向壮大的过程。</p>',10)])])}const u=e(l,[["render",n]]);export{p as __pageData,u as default};
